@Singleton
@Slf4j
class WikiMarketService
{
	private static final String API_BASE = "https://prices.runescape.wiki/api/v1/osrs";
	private static final String USER_AGENT = "osrs-ge-advisor-runelite/1.0 (external plugin)";
	private static final double GE_TAX_RATE = 0.02d;
	private static final int GE_TAX_CAP = 5_000_000;
	private static final long MAPPING_CACHE_SECONDS = 24L * 60L * 60L;

	private final Gson gson;
	private final HttpClient httpClient = HttpClient.newBuilder().build();

	private volatile Map<Integer, ItemMetadata> mappingCache = Collections.emptyMap();
	private volatile Instant mappingLoadedAt = Instant.EPOCH;

	@Inject
	WikiMarketService(Gson gson)
	{
		this.gson = gson;
	}

	MarketData refreshMarket(OsrsGeAdvisorConfig config, List<OfferSnapshot> currentOffers) throws IOException, InterruptedException
	{
		ZoneId zoneId = resolveZone(config.timezoneOverride());
		String timezoneLabel = formatZone(zoneId);
		Instant now = Instant.now();

		Map<Integer, ItemMetadata> metadata = loadMapping();
		Map<Integer, LatestPrice> latestPrices = parseLatest(fetchJsonObject("latest"));
		Map<Integer, HourlyVolume> hourlyVolumes = parseHourly(fetchJsonObject("1h"));
		List<MarketCandidate> candidates = buildCandidates(metadata.values(), latestPrices, hourlyVolumes, config, now);

		Set<Integer> timedIds = new HashSet<>();
		for (int index = 0; index < Math.min(config.historyItems(), candidates.size()); index++)
		{
			timedIds.add(candidates.get(index).getItemId());
		}
		for (OfferSnapshot offer : currentOffers)
		{
			if (!offer.isEmpty())
			{
				timedIds.add(offer.getItemId());
			}
		}

		Map<Integer, TimingInsight> timingByItem = loadTimingInsights(timedIds, zoneId);
		for (MarketCandidate candidate : candidates)
		{
			TimingInsight timingInsight = timingByItem.get(candidate.getItemId());
			if (timingInsight == null)
			{
				continue;
			}

			candidate.setBestHours(timingInsight.getBestHours());
			candidate.setCurrentWindow(timingInsight.getCurrentWindow());
			candidate.setHistoryPoints(timingInsight.getHistoryPoints());
		}

		return new MarketData(now, timezoneLabel, zoneId, metadata, latestPrices, timingByItem, candidates);
	}

	AdvisorSnapshot buildSnapshot(MarketData data, List<OfferSnapshot> currentOffers)
	{
		return new AdvisorSnapshot(
			data.getFetchedAt(),
			data.getTimezoneLabel(),
			buildOfferAdvice(currentOffers, data),
			data.getCandidates()
		);
	}

	private Map<Integer, ItemMetadata> loadMapping() throws IOException, InterruptedException
	{
		if (!mappingCache.isEmpty() && Instant.now().minusSeconds(MAPPING_CACHE_SECONDS).isBefore(mappingLoadedAt))
		{
			return mappingCache;
		}

		JsonArray mapping = fetchJsonArray("mapping");
		Map<Integer, ItemMetadata> items = new HashMap<>(mapping.size());
		for (JsonElement element : mapping)
		{
			JsonObject object = element.getAsJsonObject();
			int id = object.get("id").getAsInt();
			Integer limit = object.has("limit") && !object.get("limit").isJsonNull()
				? object.get("limit").getAsInt()
				: null;

			items.put(id, new ItemMetadata(
				id,
				object.get("name").getAsString(),
				object.get("members").getAsBoolean(),
				limit
			));
		}

		mappingCache = Collections.unmodifiableMap(items);
		mappingLoadedAt = Instant.now();
		return mappingCache;
	}

	private List<MarketCandidate> buildCandidates(
		Collection<ItemMetadata> items,
		Map<Integer, LatestPrice> latestPrices,
		Map<Integer, HourlyVolume> hourlyVolumes,
		OsrsGeAdvisorConfig config,
		Instant now)
	{
		List<MarketCandidate> candidates = new ArrayList<>();
		int maxBuyPrice = config.maxBuyPrice() <= 0 ? Integer.MAX_VALUE : config.maxBuyPrice();

		for (ItemMetadata item : items)
		{
			if (config.accountFilter() == AccountFilter.MEMBERS_ONLY && !item.isMembers())
			{
				continue;
			}
			if (config.accountFilter() == AccountFilter.F2P_ONLY && item.isMembers())
			{
				continue;
			}

			LatestPrice latest = latestPrices.get(item.getId());
			HourlyVolume hourly = hourlyVolumes.get(item.getId());
			if (latest == null || hourly == null)
			{
				continue;
			}

			if (latest.getLow() <= 0 || latest.getHigh() <= 0 || latest.getHigh() <= latest.getLow())
			{
				continue;
			}

			if (latest.getLow() < config.minBuyPrice() || latest.getLow() > maxBuyPrice)
			{
				continue;
			}

			long maxAgeMinutes = Math.max(
				Math.max(0L, now.getEpochSecond() - latest.getHighTime()) / 60L,
				Math.max(0L, now.getEpochSecond() - latest.getLowTime()) / 60L
			);
			if (maxAgeMinutes > config.maxAgeMinutes())
			{
				continue;
			}

			int hourlyVolume = Math.min(hourly.getHighPriceVolume(), hourly.getLowPriceVolume());
			int recentVolume = hourly.getHighPriceVolume() + hourly.getLowPriceVolume();
			if (hourlyVolume < config.minHourlyVolume())
			{
				continue;
			}

			int netProfitEach = computeNetProfit(latest.getLow(), latest.getHigh());
			if (netProfitEach < config.minNetProfit())
			{
				continue;
			}

			double marginPercent = (netProfitEach / (double) latest.getLow()) * 100d;
			if (marginPercent < config.minMarginPercent())
			{
				continue;
			}

			int budgetQuantity = config.capital() / latest.getLow();
			if (budgetQuantity <= 0)
			{
				continue;
			}

			int affordableQuantity = item.getLimit() == null ? budgetQuantity : Math.min(budgetQuantity, item.getLimit());
			if (affordableQuantity <= 0)
			{
				continue;
			}

			double freshness = Math.max(0.1d, 1d - (maxAgeMinutes / (double) config.maxAgeMinutes()));
			candidates.add(new MarketCandidate(
				item.getId(),
				item.getName(),
				item.isMembers(),
				item.getLimit(),
				latest.getLow(),
				latest.getHigh(),
				netProfitEach,
				marginPercent,
				hourlyVolume,
				recentVolume,
				(int) maxAgeMinutes,
				affordableQuantity,
				netProfitEach * affordableQuantity,
				freshness
			));
		}

		candidates.sort(Comparator.comparingDouble(this::scoreCandidate).reversed());
		if (candidates.size() > config.topResults())
		{
			return new ArrayList<>(candidates.subList(0, config.topResults()));
		}
		return candidates;
	}

	private double scoreCandidate(MarketCandidate candidate)
	{
		return candidate.getEstimatedProfit()
			* Math.log10(candidate.getHourlyVolume() + 10d)
			* candidate.getFreshnessScore();
	}

	private List<OfferAdvice> buildOfferAdvice(List<OfferSnapshot> currentOffers, MarketData data)
	{
		Map<Integer, OfferSnapshot> bySlot = new HashMap<>();
		for (OfferSnapshot offer : currentOffers)
		{
			bySlot.put(offer.getSlot(), offer);
		}

		Map<Integer, MarketCandidate> candidatesByItem = new HashMap<>();
		for (MarketCandidate candidate : data.getCandidates())
		{
			candidatesByItem.put(candidate.getItemId(), candidate);
		}

		List<OfferAdvice> advice = new ArrayList<>();
		for (int slot = 0; slot < 8; slot++)
		{
			OfferSnapshot offer = bySlot.get(slot);
			if (offer == null || offer.isEmpty())
			{
				advice.add(new OfferAdvice(
					slot,
					null,
					"Empty slot",
					false,
					null,
					null,
					null,
					"Waiting for a GE listing",
					"Open a buy or sell offer in-game and this slot will update live.",
					"No market comparison available until an item is placed in this slot.",
					"Timing advice appears once the slot has an active or completed offer."
				));
				continue;
			}

			ItemMetadata meta = data.getItemMetadata().get(offer.getItemId());
			LatestPrice latest = data.getLatestPrices().get(offer.getItemId());
			TimingInsight timing = data.getTimingByItem().get(offer.getItemId());
			MarketCandidate candidate = candidatesByItem.get(offer.getItemId());

			String itemName = meta != null ? meta.getName() : "Item " + offer.getItemId();
			boolean buying = offer.isBuying();
			String headline = offer.getState().name() + " | Filled " + formatNumber(offer.getQuantitySold()) + " / " + formatNumber(offer.getTotalQuantity());
			String detail = "Offer " + formatNumber(offer.getPrice()) + " gp ea | "
				+ (buying ? "Spent " : "Received ")
				+ formatNumber(offer.getSpent()) + " gp";

			String marketLine;
			if (latest == null)
			{
				marketLine = "No fresh live market price was available for this item.";
			}
			else if (buying)
			{
				int targetGap = offer.getPrice() - latest.getLow();
				int potentialFlip = computeNetProfit(offer.getPrice(), latest.getHigh());
				String stance = targetGap > 0
					? "You are paying " + formatSigned(targetGap) + " gp above the current patient buy target."
					: "You are " + formatSigned(targetGap) + " gp below the current patient buy target, so fills may be slower.";
				String flipHint = potentialFlip > 0
					? " Potential margin vs current high: " + formatNumber(potentialFlip) + " gp/ea."
					: " Current spread does not support a profitable flip after tax.";
				marketLine = "Live low/high: " + formatNumber(latest.getLow()) + " / " + formatNumber(latest.getHigh()) + " gp. "
					+ stance + flipHint;
			}
			else
			{
				int targetGap = latest.getHigh() - offer.getPrice();
				String stance = targetGap >= 0
					? "You are listing " + formatNumber(targetGap) + " gp below the current patient sell target."
					: "You are " + formatNumber(Math.abs(targetGap)) + " gp above the current patient sell target, so fills may be slower.";
				int instantFloorGap = offer.getPrice() - latest.getLow();
				marketLine = "Live low/high: " + formatNumber(latest.getLow()) + " / " + formatNumber(latest.getHigh()) + " gp. "
					+ stance + " Your listing is " + formatSigned(instantFloorGap) + " gp versus the instant-sell floor.";
			}

			String timingLine;
			if (timing == null || timing.getHistoryPoints() <= 0)
			{
				timingLine = "No strong timing signal yet for this item.";
			}
			else
			{
				String windowMessage;
				switch (timing.getCurrentWindow())
				{
					case "good":
						windowMessage = "This is a strong hour right now.";
						break;
					case "ok":
						windowMessage = "This hour is usable, but not the strongest.";
						break;
					default:
						windowMessage = "Recent history suggests waiting for a stronger hour if you can.";
						break;
				}

				String bestHours = timing.getBestHours().isEmpty()
					? "No best hours found"
					: String.join(", ", timing.getBestHours());
				timingLine = "Best hours: " + bestHours + " | Window: " + timing.getCurrentWindow()
					+ ". " + windowMessage;
			}

			if (candidate != null)
			{
				timingLine += " This item is also in the current recommendation list.";
			}

			advice.add(new OfferAdvice(
				slot,
				offer,
				itemName,
				meta != null && meta.isMembers(),
				meta != null ? meta.getLimit() : null,
				latest != null ? latest.getLow() : null,
				latest != null ? latest.getHigh() : null,
				headline,
				detail,
				marketLine,
				timingLine
			));
		}

		return advice;
	}

	private Map<Integer, TimingInsight> loadTimingInsights(Set<Integer> itemIds, ZoneId zoneId) throws IOException, InterruptedException
	{
		Map<Integer, TimingInsight> timings = new HashMap<>();
		for (Integer itemId : itemIds)
		{
			TimingInsight timing = loadTimingInsight(itemId, zoneId);
			if (timing != null)
			{
				timings.put(itemId, timing);
			}
		}
		return timings;
	}

	private TimingInsight loadTimingInsight(int itemId, ZoneId zoneId) throws IOException, InterruptedException
	{
		JsonObject response = fetchJsonObject("timeseries?timestep=1h&id=" + itemId);
		JsonArray data = response.getAsJsonArray("data");
		if (data == null || data.size() == 0)
		{
			return null;
		}

		Map<Integer, List<Integer>> profitsByHour = new HashMap<>();
		Map<Integer, List<Integer>> liquidityByHour = new HashMap<>();

		for (JsonElement element : data)
		{
			JsonObject point = element.getAsJsonObject();
			if (!point.has("avgHighPrice") || !point.has("avgLowPrice")
				|| point.get("avgHighPrice").isJsonNull() || point.get("avgLowPrice").isJsonNull())
			{
				continue;
			}

			int avgHigh = point.get("avgHighPrice").getAsInt();
			int avgLow = point.get("avgLowPrice").getAsInt();
			if (avgHigh <= avgLow)
			{
				continue;
			}

			int highVolume = point.has("highPriceVolume") && !point.get("highPriceVolume").isJsonNull()
				? point.get("highPriceVolume").getAsInt()
				: 0;
			int lowVolume = point.has("lowPriceVolume") && !point.get("lowPriceVolume").isJsonNull()
				? point.get("lowPriceVolume").getAsInt()
				: 0;
			int twoSidedVolume = Math.min(highVolume, lowVolume);
			if (twoSidedVolume <= 0)
			{
				continue;
			}

			int netProfit = computeNetProfit(avgLow, avgHigh);
			if (netProfit <= 0)
			{
				continue;
			}

			int hour = Instant.ofEpochSecond(point.get("timestamp").getAsLong())
				.atZone(zoneId)
				.getHour();

			profitsByHour.computeIfAbsent(hour, ignored -> new ArrayList<>()).add(netProfit);
			liquidityByHour.computeIfAbsent(hour, ignored -> new ArrayList<>()).add(twoSidedVolume);
		}

		if (profitsByHour.isEmpty())
		{
			return null;
		}

		Map<Integer, Double> scores = new HashMap<>();
		for (Map.Entry<Integer, List<Integer>> entry : profitsByHour.entrySet())
		{
			int hour = entry.getKey();
			double medianProfit = median(entry.getValue());
			double medianLiquidity = median(liquidityByHour.getOrDefault(hour, Collections.emptyList()));
			scores.put(hour, medianProfit * Math.log10(medianLiquidity + 10d));
		}

		List<Map.Entry<Integer, Double>> best = new ArrayList<>(scores.entrySet());
		best.sort(Map.Entry.<Integer, Double>comparingByValue().reversed());

		List<String> bestHours = new ArrayList<>();
		for (int i = 0; i < Math.min(2, best.size()); i++)
		{
			bestHours.add(String.format(Locale.US, "%02d:00", best.get(i).getKey()));
		}

		int currentHour = ZonedDateTime.now(zoneId).getHour();
		double currentScore = scores.getOrDefault(currentHour, 0d);
		double bestScore = best.isEmpty() ? 0d : best.get(0).getValue();
		String currentWindow;
		if (bestScore <= 0d)
		{
			currentWindow = "unknown";
		}
		else if (currentScore >= bestScore * 0.85d)
		{
			currentWindow = "good";
		}
		else if (currentScore >= bestScore * 0.55d)
		{
			currentWindow = "ok";
		}
		else
		{
			currentWindow = "wait";
		}

		int historyPoints = 0;
		for (List<Integer> values : profitsByHour.values())
		{
			historyPoints += values.size();
		}

		return new TimingInsight(bestHours, currentWindow, historyPoints);
	}

	private JsonObject fetchJsonObject(String path) throws IOException, InterruptedException
	{
		HttpRequest request = HttpRequest.newBuilder()
			.uri(URI.create(API_BASE + "/" + encodePath(path)))
			.header("Accept", "application/json")
			.header("User-Agent", USER_AGENT)
			.GET()
			.build();

		HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
		if (response.statusCode() < 200 || response.statusCode() >= 300)
		{
			throw new IOException("Wiki price API returned HTTP " + response.statusCode());
		}

		JsonElement element = gson.fromJson(response.body(), JsonElement.class);
		if (!element.isJsonObject())
		{
			throw new IOException("Unexpected JSON response for " + path);
		}
		return element.getAsJsonObject();
	}

	private JsonArray fetchJsonArray(String path) throws IOException, InterruptedException
	{
		HttpRequest request = HttpRequest.newBuilder()
			.uri(URI.create(API_BASE + "/" + encodePath(path)))
			.header("Accept", "application/json")
			.header("User-Agent", USER_AGENT)
			.GET()
			.build();

		HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
		if (response.statusCode() < 200 || response.statusCode() >= 300)
		{
			throw new IOException("Wiki price API returned HTTP " + response.statusCode());
		}

		JsonElement element = gson.fromJson(response.body(), JsonElement.class);
		if (!element.isJsonArray())
		{
			throw new IOException("Unexpected JSON response for " + path);
		}
		return element.getAsJsonArray();
	}

	private String encodePath(String path)
	{
		if (!path.contains("?"))
		{
			return path;
		}

		String[] parts = path.split("\\?", 2);
		StringBuilder query = new StringBuilder();
		String[] pairs = parts[1].split("&");
		for (int index = 0; index < pairs.length; index++)
		{
			if (index > 0)
			{
				query.append('&');
			}

			String[] pair = pairs[index].split("=", 2);
			query.append(URLEncoder.encode(pair[0], StandardCharsets.UTF_8));
			if (pair.length > 1)
			{
				query.append('=').append(URLEncoder.encode(pair[1], StandardCharsets.UTF_8));
			}
		}
		return parts[0] + "?" + query;
	}

	private Map<Integer, LatestPrice> parseLatest(JsonObject object)
	{
		JsonObject data = object.getAsJsonObject("data");
		if (data == null)
		{
			return Collections.emptyMap();
		}

		Map<Integer, LatestPrice> prices = new HashMap<>();
		for (Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			JsonObject value = entry.getValue().getAsJsonObject();
			if (!value.has("high") || !value.has("low")
				|| value.get("high").isJsonNull() || value.get("low").isJsonNull())
			{
				continue;
			}

			prices.put(Integer.parseInt(entry.getKey()), new LatestPrice(
				value.get("high").getAsInt(),
				value.get("highTime").getAsLong(),
				value.get("low").getAsInt(),
				value.get("lowTime").getAsLong()
			));
		}
		return prices;
	}

	private Map<Integer, HourlyVolume> parseHourly(JsonObject object)
	{
		JsonObject data = object.getAsJsonObject("data");
		if (data == null)
		{
			return Collections.emptyMap();
		}

		Map<Integer, HourlyVolume> prices = new HashMap<>();
		for (Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			JsonObject value = entry.getValue().getAsJsonObject();
			prices.put(Integer.parseInt(entry.getKey()), new HourlyVolume(
				asInt(value, "avgHighPrice"),
				asInt(value, "highPriceVolume"),
				asInt(value, "avgLowPrice"),
				asInt(value, "lowPriceVolume")
			));
		}
		return prices;
	}

	private int asInt(JsonObject object, String key)
	{
		return object.has(key) && !object.get(key).isJsonNull() ? object.get(key).getAsInt() : 0;
	}

	private ZoneId resolveZone(String raw)
	{
		String trimmed = raw == null ? "" : raw.trim();
		if (trimmed.isEmpty())
		{
			return ZoneId.systemDefault();
		}

		try
		{
			return ZoneId.of(trimmed);
		}
		catch (DateTimeException ex)
		{
			try
			{
				return ZoneOffset.of(trimmed);
			}
			catch (DateTimeException ignored)
			{
				log.debug("Invalid timezone override '{}', using system default", trimmed);
				return ZoneId.systemDefault();
			}
		}
	}

	private String formatZone(ZoneId zoneId)
	{
		return ZonedDateTime.now(zoneId).format(DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm z"));
	}

	private static int computeNetProfit(int buyPrice, int sellPrice)
	{
		return sellPrice - buyPrice - computeTax(sellPrice);
	}

	private static int computeTax(int price)
	{
		return Math.min((int) Math.floor(price * GE_TAX_RATE), GE_TAX_CAP);
	}

	private static double median(List<Integer> values)
	{
		if (values == null || values.isEmpty())
		{
			return 0d;
		}

		List<Integer> sorted = new ArrayList<>(values);
		sorted.sort(Integer::compareTo);
		int middle = sorted.size() / 2;
		if ((sorted.size() & 1) == 1)
		{
			return sorted.get(middle);
		}
		return (sorted.get(middle - 1) + sorted.get(middle)) / 2d;
	}

	static String formatNumber(int value)
	{
		return String.format(Locale.US, "%,d", value);
	}

	private static String formatSigned(int value)
	{
		if (value > 0)
		{
			return String.format(Locale.US, "+%,d", value);
		}
		return String.format(Locale.US, "%,d", value);
	}

	@Value
	static class LatestPrice
	{
		int high;
		long highTime;
		int low;
		long lowTime;
	}

	@Value
	private static class HourlyVolume
	{
		int avgHighPrice;
		int highPriceVolume;
		int avgLowPrice;
		int lowPriceVolume;
	}
}

