import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

class OsrsGeAdvisorPanel extends PluginPanel
{
	private static final DateTimeFormatter HEADER_TIME = DateTimeFormatter.ofPattern("HH:mm:ss");
	private static final Color GOOD_COLOR = new Color(0x2ECC71);
	private static final Color OK_COLOR = new Color(0xF1C40F);
	private static final Color WAIT_COLOR = new Color(0xE74C3C);

	private final ItemManager itemManager;

	private final JLabel summaryLabel = new JLabel("Waiting for first market sync...");
	private final JLabel statusLabel = new JLabel("Ready");
	private final DynamicButton refreshButton;
	private final JPanel offersContainer = new JPanel();
	private final JPanel candidatesContainer = new JPanel();

	@Inject
	OsrsGeAdvisorPanel(OsrsGeAdvisorPlugin plugin, ItemManager itemManager)
	{
		super(false);
		this.itemManager = itemManager;
		this.refreshButton = new DynamicButton("Refresh now", plugin::requestManualRefresh);

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel top = new JPanel();
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));

		JLabel titleLabel = new JLabel("OSRS GE Advisor");
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);
		titleLabel.setAlignmentX(LEFT_ALIGNMENT);

		summaryLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		summaryLabel.setFont(FontManager.getRunescapeSmallFont());
		summaryLabel.setAlignmentX(LEFT_ALIGNMENT);

		statusLabel.setForeground(ColorScheme.BRAND_ORANGE);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setAlignmentX(LEFT_ALIGNMENT);

		refreshButton.setAlignmentX(LEFT_ALIGNMENT);

		top.add(titleLabel);
		top.add(Box.createVerticalStrut(4));
		top.add(summaryLabel);
		top.add(Box.createVerticalStrut(4));
		top.add(statusLabel);
		top.add(Box.createVerticalStrut(8));
		top.add(refreshButton);

		JPanel content = new JPanel();
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(BorderFactory.createEmptyBorder(0, 10, 10, 10));

		offersContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		offersContainer.setLayout(new BoxLayout(offersContainer, BoxLayout.Y_AXIS));

		candidatesContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		candidatesContainer.setLayout(new BoxLayout(candidatesContainer, BoxLayout.Y_AXIS));

		content.add(sectionHeader("Your GE Slots"));
		content.add(offersContainer);
		content.add(Box.createVerticalStrut(10));
		content.add(sectionHeader("Live Flip Ideas"));
		content.add(candidatesContainer);

		JScrollPane scrollPane = new JScrollPane(content);
		scrollPane.setBorder(null);
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);

		add(top, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
	}

	void setLoading(boolean loading)
	{
		refreshButton.setEnabled(!loading);
		statusLabel.setText(loading ? "Refreshing live OSRS Wiki prices and GE slot analysis..." : statusLabel.getText());
	}

	void setError(String message)
	{
		statusLabel.setText(message);
		statusLabel.setForeground(WAIT_COLOR);
		refreshButton.setEnabled(true);
	}

	void setSnapshot(AdvisorSnapshot snapshot, int capital)
	{
		refreshButton.setEnabled(true);
		statusLabel.setForeground(ColorScheme.BRAND_ORANGE);
		summaryLabel.setText(
			"Updated "
				+ HEADER_TIME.format(snapshot.getFetchedAt().atZone(ZoneId.systemDefault()))
				+ " | Capital "
				+ WikiMarketService.formatNumber(capital)
				+ " gp | "
				+ snapshot.getTimezoneLabel()
		);
		statusLabel.setText("Live data synced. GE slots will continue updating when offers change.");

		renderOffers(snapshot.getOffers());
		renderCandidates(snapshot.getCandidates());
		revalidate();
		repaint();
	}

	void updateStatus(String message)
	{
		statusLabel.setForeground(ColorScheme.BRAND_ORANGE);
		statusLabel.setText(message);
	}

	private JPanel sectionHeader(String text)
	{
		JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));

		JLabel label = new JLabel(text);
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeBoldFont());
		panel.add(label, BorderLayout.WEST);
		return panel;
	}

	private void renderOffers(List<OfferAdvice> offers)
	{
		offersContainer.removeAll();
		for (OfferAdvice offer : offers)
		{
			offersContainer.add(buildOfferCard(offer));
			offersContainer.add(Box.createVerticalStrut(8));
		}
	}

	private void renderCandidates(List<MarketCandidate> candidates)
	{
		candidatesContainer.removeAll();
		if (candidates.isEmpty())
		{
			candidatesContainer.add(emptyState("No items matched the current filters."));
			return;
		}

		for (MarketCandidate candidate : candidates)
		{
			candidatesContainer.add(buildCandidateCard(candidate));
			candidatesContainer.add(Box.createVerticalStrut(8));
		}
	}

	private JPanel buildOfferCard(OfferAdvice advice)
	{
		JPanel card = baseCard();
		card.setLayout(new BorderLayout(8, 0));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(40, 40));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (advice.getOffer() != null)
		{
			AsyncBufferedImage image = itemManager.getImage(advice.getOffer().getItemId(), Math.max(advice.getOffer().getTotalQuantity(), 1), true);
			image.addTo(icon);
		}
		card.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));

		JLabel title = new JLabel("Slot " + (advice.getSlot() + 1) + " - " + advice.getItemName());
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());

		JLabel headline = line(advice.getHeadline(), advice.getOffer() != null ? stateColor(advice.getOffer().getState().name()) : ColorScheme.LIGHT_GRAY_COLOR);
		JLabel detail = line(advice.getDetailLine(), ColorScheme.LIGHT_GRAY_COLOR);
		JLabel market = line(advice.getMarketLine(), ColorScheme.LIGHT_GRAY_COLOR);
		JLabel timing = line(advice.getTimingLine(), ColorScheme.LIGHT_GRAY_COLOR);

		text.add(title);
		text.add(Box.createVerticalStrut(2));
		text.add(headline);
		text.add(detail);
		text.add(market);
		text.add(timing);

		card.add(text, BorderLayout.CENTER);
		return card;
	}

	private JPanel buildCandidateCard(MarketCandidate candidate)
	{
		JPanel card = baseCard();
		card.setLayout(new BorderLayout(8, 0));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(40, 40));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		itemManager.getImage(candidate.getItemId(), Math.max(candidate.getAffordableQuantity(), 1), true).addTo(icon);
		card.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));

		JLabel title = new JLabel(candidate.getName());
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());

		String topLine = "Buy " + WikiMarketService.formatNumber(candidate.getBuyPrice())
			+ " -> Sell " + WikiMarketService.formatNumber(candidate.getSellPrice())
			+ " | Net " + WikiMarketService.formatNumber(candidate.getNetProfitEach()) + "/ea";
		String middleLine = "Qty " + WikiMarketService.formatNumber(candidate.getAffordableQuantity())
			+ " | Est " + WikiMarketService.formatNumber(candidate.getEstimatedProfit())
			+ " gp | 1h vol " + WikiMarketService.formatNumber(candidate.getHourlyVolume());
		String bestHours = candidate.getBestHours().isEmpty() ? "-" : String.join(", ", candidate.getBestHours());
		String bottomLine = "Best hours " + bestHours
			+ " | Now " + candidate.getCurrentWindow()
			+ " | Margin " + String.format("%.2f%%", candidate.getMarginPercent())
			+ " | Age " + candidate.getMaxAgeMinutes() + "m";

		text.add(title);
		text.add(Box.createVerticalStrut(2));
		text.add(line(topLine, ColorScheme.LIGHT_GRAY_COLOR));
		text.add(line(middleLine, ColorScheme.LIGHT_GRAY_COLOR));
		text.add(line(bottomLine, timingColor(candidate.getCurrentWindow())));

		card.add(text, BorderLayout.CENTER);
		return card;
	}

	private JPanel emptyState(String text)
	{
		JPanel panel = baseCard();
		panel.setLayout(new BorderLayout());
		panel.add(line(text, ColorScheme.LIGHT_GRAY_COLOR), BorderLayout.CENTER);
		return panel;
	}

	private JPanel baseCard()
	{
		JPanel card = new JPanel();
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(8, 8, 8, 8)
		));
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 150));
		return card;
	}

	private JLabel line(String text, Color color)
	{
		JLabel label = new JLabel("<html><body style='width:320px'>" + escape(text) + "</body></html>");
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeSmallFont());
		return label;
	}

	private String escape(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}

	private Color timingColor(String currentWindow)
	{
		if ("good".equalsIgnoreCase(currentWindow))
		{
			return GOOD_COLOR;
		}
		if ("ok".equalsIgnoreCase(currentWindow))
		{
			return OK_COLOR;
		}
		if ("wait".equalsIgnoreCase(currentWindow))
		{
			return WAIT_COLOR;
		}
		return ColorScheme.LIGHT_GRAY_COLOR;
	}

	private Color stateColor(String state)
	{
		if (state.startsWith("BUY"))
		{
			return GOOD_COLOR;
		}
		if (state.startsWith("SELL"))
		{
			return OK_COLOR;
		}
		if (state.startsWith("CANCELLED"))
		{
			return WAIT_COLOR;
		}
		return ColorScheme.LIGHT_GRAY_COLOR;
	}

	private static final class DynamicButton extends javax.swing.JButton
	{
		private DynamicButton(String text, Runnable action)
		{
			super(text);
			addActionListener(event -> action.run());
		}
	}
}

