import lombok.Value;

@Value
class MarketData
{
	Instant fetchedAt;
	String timezoneLabel;
	ZoneId zoneId;
	Map<Integer, ItemMetadata> itemMetadata;
	Map<Integer, WikiMarketService.LatestPrice> latestPrices;
	Map<Integer, TimingInsight> timingByItem;
	List<MarketCandidate> candidates;
}

package com.arturas.osrsgeadvisor;

import lombok.Value;
import net.runelite.api.GrandExchangeOfferState;

@Value
public class OfferSnapshot
{
	int slot;
	int itemId;
	int price;
	int totalQuantity;
	int quantitySold;
	int spent;
	GrandExchangeOfferState state;

	public boolean isEmpty()
	{
		return state == null || state == GrandExchangeOfferState.EMPTY || itemId <= 0;
	}

	public boolean isBuying()
	{
		return state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
	}
}

package com.arturas.osrsgeadvisor;

import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
