@PluginDescriptor(
	name = "OSRS GE Advisor",
	description = "Track your actual GE offers and compare them with live market spreads",
	tags = {"grand exchange", "ge", "market", "panel", "prices", "trade"}
)
@Slf4j
public class OsrsGeAdvisorPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ScheduledExecutorService scheduledExecutorService;

	@Inject
	private WikiMarketService marketService;

	@Inject
	private OsrsGeAdvisorConfig config;

	private final Map<Integer, OfferSnapshot> offersBySlot = new ConcurrentHashMap<>();
	private final AtomicBoolean refreshInProgress = new AtomicBoolean(false);

	private NavigationButton navButton;
	private OsrsGeAdvisorPanel panel;
	private ScheduledFuture<?> refreshFuture;
	private volatile MarketData lastMarketData;
	private volatile AdvisorSnapshot lastSnapshot;

	@Provides
	OsrsGeAdvisorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OsrsGeAdvisorConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new OsrsGeAdvisorPanel(this, itemManager);

		navButton = NavigationButton.builder()
			.tooltip("OSRS GE Advisor")
			.icon(buildSidebarIcon())
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		scheduleRefreshLoop();
		captureOffersFromClient();
		requestRefresh("Plugin started");
	}

	@Override
	protected void shutDown()
	{
		if (refreshFuture != null)
		{
			refreshFuture.cancel(false);
			refreshFuture = null;
		}

		offersBySlot.clear();
		lastMarketData = null;
		lastSnapshot = null;

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"osrsGeAdvisor".equals(event.getGroup()))
		{
			return;
		}

		scheduleRefreshLoop();
		requestRefresh("Config changed");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			captureOffersFromClient();
			requestRefresh("Logged in");
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			offersBySlot.clear();
			pushCachedSnapshot("Logged out. Waiting for the next in-game GE state.");
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		updateOfferSnapshot(event.getSlot(), event.getOffer());
		pushCachedSnapshot("GE offer updated in slot " + (event.getSlot() + 1) + ".");
	}

	void requestManualRefresh()
	{
		requestRefresh("Manual refresh requested");
	}

	private void scheduleRefreshLoop()
	{
		if (refreshFuture != null)
		{
			refreshFuture.cancel(false);
		}

		refreshFuture = scheduledExecutorService.scheduleWithFixedDelay(
			() -> refreshMarket("Scheduled refresh"),
			0L,
			Math.max(1, config.refreshMinutes()),
			TimeUnit.MINUTES
		);
	}

	private void requestRefresh(String reason)
	{
		scheduledExecutorService.execute(() -> refreshMarket(reason));
	}

	private void refreshMarket(String reason)
	{
		if (!refreshInProgress.compareAndSet(false, true))
		{
			return;
		}

		List<OfferSnapshot> currentOffers = currentOffers();
		SwingUtilities.invokeLater(() ->
		{
			panel.setLoading(true);
			panel.updateStatus(reason + ". Pulling live market data...");
		});

		try
		{
			MarketData marketData = marketService.refreshMarket(config, currentOffers);
			AdvisorSnapshot snapshot = marketService.buildSnapshot(marketData, currentOffers);
			lastMarketData = marketData;
			lastSnapshot = snapshot;
			SwingUtilities.invokeLater(() -> panel.setSnapshot(snapshot, config.capital()));
		}
		catch (InterruptedException ex)
		{
			Thread.currentThread().interrupt();
			log.warn("Interrupted while refreshing OSRS GE market data", ex);
			SwingUtilities.invokeLater(() -> panel.setError("Live refresh interrupted."));
		}
		catch (IOException ex)
		{
			log.warn("Unable to refresh OSRS GE market data", ex);
			SwingUtilities.invokeLater(() -> panel.setError("Live refresh failed: " + ex.getMessage()));
		}
		catch (Exception ex)
		{
			log.warn("Unexpected OSRS GE Advisor refresh failure", ex);
			SwingUtilities.invokeLater(() -> panel.setError("Unexpected refresh error: " + ex.getMessage()));
		}
		finally
		{
			refreshInProgress.set(false);
		}
	}

	private void captureOffersFromClient()
	{
		clientThread.invokeLater(() ->
		{
			GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
			if (offers == null)
			{
				return;
			}

			for (int slot = 0; slot < offers.length; slot++)
			{
				updateOfferSnapshot(slot, offers[slot]);
			}
			pushCachedSnapshot("Captured current GE slots from RuneLite.");
		});
	}

	private void updateOfferSnapshot(int slot, GrandExchangeOffer offer)
	{
		if (offer == null || offer.getState() == null || offer.getState().name().equals("EMPTY") || offer.getItemId() <= 0)
		{
			offersBySlot.remove(slot);
			return;
		}

		offersBySlot.put(slot, new OfferSnapshot(
			slot,
			offer.getItemId(),
			offer.getPrice(),
			offer.getTotalQuantity(),
			offer.getQuantitySold(),
			offer.getSpent(),
			offer.getState()
		));
	}

	private List<OfferSnapshot> currentOffers()
	{
		List<OfferSnapshot> offers = new ArrayList<>(offersBySlot.values());
		offers.sort(Comparator.comparingInt(OfferSnapshot::getSlot));
		return offers;
	}

	private void pushCachedSnapshot(String status)
	{
		MarketData marketData = lastMarketData;
		if (marketData == null)
		{
			SwingUtilities.invokeLater(() -> panel.updateStatus(status));
			return;
		}

		AdvisorSnapshot snapshot = marketService.buildSnapshot(marketData, currentOffers());
		lastSnapshot = snapshot;
		SwingUtilities.invokeLater(() ->
		{
			panel.setSnapshot(snapshot, config.capital());
			panel.updateStatus(status);
		});
	}

	private BufferedImage buildSidebarIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(new Color(0x1F2937));
			graphics.fill(new RoundRectangle2D.Double(0.5d, 0.5d, 15d, 15d, 4d, 4d));

			graphics.setColor(new Color(0xF59E0B));
			graphics.fillOval(2, 7, 6, 6);
			graphics.fillOval(5, 4, 6, 6);
			graphics.fillOval(8, 7, 6, 6);

			graphics.setColor(Color.WHITE);
			graphics.setStroke(new BasicStroke(1.75f));
			graphics.drawLine(3, 5, 7, 2);
			graphics.drawLine(7, 2, 11, 6);
			graphics.drawLine(11, 6, 13, 4);
		}
		finally
		{
			graphics.dispose();
		}

		return image;
	}
